using System;using System.Collections;using System.IO;using System.Linq;using IdleRestaurant;using UnityEngine;
public static class PoseCheck{
 static RestaurantApp app;public static void Main(){app=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();app.StartCoroutine(Run());}
 static IEnumerator Run(){string old=Newtonsoft.Json.JsonConvert.SerializeObject(app.Game.State);try{app.Game.State=new RestaurantGame(app.catalog).State;app.Game.State.introComplete=true;app.Game.State.guideStep=6;app.Navigate("play");app.world.Show(0);app.Game.BeginService();float began=Time.realtimeSinceStartup;ServiceGuest guest=null;while(Time.realtimeSinceStartup-began<80){guest=app.Game.State.outlets[0].service?.FirstOrDefault(g=>g.phase==GuestPhase.Eating);if(guest!=null)break;yield return null;}if(guest==null)throw new Exception("No eating guest");yield return new WaitForEndOfFrame();var chair=app.world.room.GetComponentsInChildren<RestaurantSeat>().First(s=>s.index==guest.seat);var rig=app.world.room.GetComponentsInChildren<RestaurantActorRig>().OrderBy(r=>Vector3.Distance(r.transform.localPosition,chair.SeatedPosition)).First();var cushion=chair.transform.Find("Rounded block").GetComponent<Renderer>().bounds;float thighMin=Mathf.Min(rig.leftLeg.Find("Capsule").GetComponent<Renderer>().bounds.min.y,rig.rightLeg.Find("Capsule").GetComponent<Renderer>().bounds.min.y);Vector3 forward=Quaternion.Euler(0,chair.yaw,0)*Vector3.back;float calfClear=float.MaxValue;foreach(var k in new[]{rig.leftKnee,rig.rightKnee}){if(!k)throw new Exception("Missing knee");foreach(var renderer in k.GetComponentsInChildren<Renderer>()){var b=renderer.bounds;float min=Vector3.Dot(b.center-chair.transform.position,forward)-Mathf.Abs(forward.x)*b.extents.x-Mathf.Abs(forward.z)*b.extents.z;calfClear=Mathf.Min(calfClear,min-.325f);}}if(thighMin<cushion.max.y-.001f||calfClear<-.001f)throw new Exception("Seated geometry clips cushion: "+thighMin+" / "+cushion.max.y+" calf "+calfClear);var t=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);t.Apply();File.WriteAllBytes("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/SeatedPose.png",t.EncodeToPNG());UnityEngine.Object.Destroy(t);var screen=app.gameCamera.WorldToScreenPoint(chair.transform.position+Vector3.up*.6f);File.WriteAllText("/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/PoseCheck.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status="PASS",thighClearance=thighMin-cushion.max.y,calfAndFootFrontClearance=calfClear,seat=guest.seat,screen=new{x=screen.x,y=screen.y},scope="Live Eating phase with actual chair cushion and articulated calf/shoe renderer bounds"},Newtonsoft.Json.Formatting.Indented));}finally{app.Game.State=new RestaurantGame(app.catalog,Newtonsoft.Json.JsonConvert.DeserializeObject<SaveState>(old)).State;app.Navigate("play");app.world.Show(app.Game.State.selected);app.Save();}}
}
